export function calculateCharge(hours: number) {
  if (hours <= 8) return hours * 20;
  return 8 * 20 + (hours - 8) * 30;
}

// Version B
const REGULAR_RATE = 20;
const OVERTIME_RATE = 30;
const REGULAR_HOURS = 8;
export function calculateCharge(hours: number) {
  if (hours <= REGULAR_HOURS) return hours * REGULAR_RATE;
  return REGULAR_HOURS * REGULAR_RATE + (hours - REGULAR_HOURS) * OVERTIME_RATE;
}
